import React, { useState } from 'react';
import axios from 'axios'; // Backend එකට Request යැවීමට axios import කළා
import Navbar from './components/Navbar';
import Home from './components/Home';
import Timetable from './components/Timetable';
import Teachers from './components/Teachers';
import About from './components/About';
import LmsDashboard from './components/LmsDashboard'; // Admin Dashboard
import StudentDashboard from './components/StudentDashboard';
import TeacherDashboard from './components/TeacherDashboard';
import Footer from './components/Footer';
import Login from './components/Login';

export default function App() {
  const [currentPage, setCurrentPage] = useState('Home');
  const [showLoginModal, setShowLoginModal] = useState(false);
  const [isLoggedIn, setIsLoggedIn] = useState(false);
  const [userRole, setUserRole] = useState(null); // 'admin', 'teacher', 'student'
  const [userName, setUserName] = useState('User');
  const [userId, setUserId] = useState(null); // Database එකේ user_id එක තබා ගැනීමට (Password වෙනස් කරද්දී ඕන වෙනවා)

  const isDashboard = isLoggedIn && currentPage === 'Dashboard';

  // 🌐 සැබෑ MySQL Database එකට සම්බන්ධ වෙන ලොගින් ෆන්ක්ෂන් එක
  const handleLoginSubmit = async (username, password) => {
    try {
      // ඔයාගේ Node.js backend එක රන් වෙන URL එක මෙතනට දාන්න (උදාහරණයක් ලෙස localhost:5000)
      const response = await axios.post('http://localhost:5000/api/login', {
        username: username,
        password: password
      });

      // Backend එකෙන් සාර්ථකව දත්ත ලැබුණොත් (e.g. { success: true, role: 'student', name: 'Nimal', id: 4 })
      if (response.data.success) {
        setIsLoggedIn(true);
        setUserRole(response.data.role); // Database එකෙන් එන role එක (admin/teacher/student)
        setUserName(response.data.name); // Database එකෙන් එන නම
        setUserId(response.data.id);     // Database එකේ user id එක
        
        setCurrentPage('Dashboard'); // කෙලින්ම Dashboard එකට යවනවා
        setShowLoginModal(false);
      }
    } catch (error) {
      // වැරදි password එකක් ගැහුවොත් හෝ සර්වර් එකේ අවුලක් ආවොත්
      const errorMsg = error.response?.data?.message || "පරිශීලක නාමය හෝ මුරපදය වැරදියි!";
      alert(`❌ ලොගින් වීමට නොහැක: ${errorMsg}`);
    }
  };

  const handleLogout = () => {
    setIsLoggedIn(false);
    setUserRole(null);
    setUserName('User');
    setUserId(null);
    setCurrentPage('Home');
  };

  return (
    <div style={{ display: 'flex', flexDirection: 'column', minHeight: '100vh' }}>
      
      {!isDashboard && (
        <Navbar 
           onLoginClick={() => setShowLoginModal(true)} 
           isLoggedIn={isLoggedIn} 
           userName={userName}
           setCurrentPage={setCurrentPage} 
           currentPage={currentPage}
        />
      )}

      <main style={{ flex: 1, display: 'flex', flexDirection: 'column' }}>
        {currentPage === 'Home' && <Home />}
        {currentPage === 'Classes' && <Timetable />}
        {currentPage === 'Teachers' && <Teachers />}
        {currentPage === 'About' && <About />}
        
        {/* Dynamic Dashboard Navigation based on MySQL Database Role */}
        {currentPage === 'Dashboard' && isLoggedIn && (
          <div style={{ flex: 1, display: 'flex', flexDirection: 'column' }}>
            {userRole === 'admin' && <LmsDashboard userName={userName} handleLogout={handleLogout} />}
            {userRole === 'teacher' && <TeacherDashboard userName={userName} userId={userId} handleLogout={handleLogout} />}
            {userRole === 'student' && <StudentDashboard userName={userName} userId={userId} handleLogout={handleLogout} />}
          </div>
        )}
      </main>

      {!isDashboard && <Footer />}

      {showLoginModal && (
        <Login 
          setShowLoginModal={setShowLoginModal} 
          handleLoginSubmit={handleLoginSubmit} 
        />
      )}
    </div>
  );
}
